#disadvantages of list

#1.slow operations for insertion and deletion in middle
#2.slow search operations
#3.fixed size
#advantages of list
#top k elements 
# top k elements
nums = [5,3,1,1,1,3,73,1]
k = 2

# frequency map
d = {}
for num in nums:
    if num not in d:
        d[num] = 1
    else:
        d[num] += 1

# bucket map
d2 = {}
maxval = 0

for key, value in d.items():   # ✅ items()
    if value not in d2:
        d2[value] = []
    d2[value].append(key)

    if value > maxval:         # ✅ value, not pair.value
        maxval = value

# collect result
result = []
while maxval > 0 and len(result) < k:
    if maxval in d2:
        while len(d2[maxval]) > 0 and len(result) < k:
            result.append(d2[maxval].pop())
    maxval -= 1
 
# final output as required
result.sort()
print(result)
